import { useSubscription } from '@proton/account/subscription/hooks';
import { useUser } from '@proton/account/user/hooks';
import { ButtonLike } from '@proton/atoms';
import Icon from '@proton/components/components/icon/Icon';
import SettingsLink from '@proton/components/components/link/SettingsLink';
import type { ModalProps } from '@proton/components/components/modalTwo/Modal';
import ModalTwo from '@proton/components/components/modalTwo/Modal';
import ModalTwoContent from '@proton/components/components/modalTwo/ModalContent';
import ModalTwoFooter from '@proton/components/components/modalTwo/ModalFooter';
import ModalTwoHeader from '@proton/components/components/modalTwo/ModalHeader';
import StripedItem from '@proton/components/components/stripedList/StripedItem';
import { StripedList } from '@proton/components/components/stripedList/StripedList';
import { REACTIVATE_SOURCE } from '@proton/components/containers/payments/subscription/cancellationFlow/useCancellationTelemetry';
import { FeatureCode, useFeature } from '@proton/features';
import subscriptionEnding from '@proton/styles/assets/img/illustrations/subscription_ending.svg';

import { getReminderPageConfig } from '../cancellationFlow/reminderPageConfig';
import type { ReminderFlag } from './cancellationReminderHelper';
import { markRemindersAsSeen } from './cancellationReminderHelper';

const CancellationReminderModal = (props: ModalProps) => {
    const [user] = useUser();
    const [subscription, subscriptionLoading] = useSubscription();

    const { feature, update } = useFeature<ReminderFlag>(FeatureCode.AutoDowngradeReminder);

    const config = getReminderPageConfig({ subscription, user });

    const markAsSeen = () => {
        if (!feature?.Value || Array.isArray(feature.Value)) {
            return;
        }

        const newValue = markRemindersAsSeen(feature.Value);
        void update(newValue);
        props?.onClose?.();
    };

    if (!subscription || subscriptionLoading) {
        return;
    }

    const formattedEndDate = format(fromUnixTime(subscription.PeriodEnd), 'PP');

    return (
        <ModalTwo {...props} onClose={markAsSeen}>
            <ModalTwoHeader />
            <ModalTwoContent>
                <section className="flex justify-center mb-4">
                    <img src={subscriptionEnding} alt="" className="mb-4" />
                    <p className="m-0 text-2xl text-bold">{c('Cancellation reminder')
                        .t`Your subscription is ending soon`}</p>
                    <p className="m-0 color-weak">{c('Cancellation reminder')
                        .t`Reactivate by ${formattedEndDate} to keep these features:`}</p>
                </section>
                <StripedList className="my-0" alternate="odd">
                    {config?.features.features.map(({ icon, text }) => (
                        <StripedItem key={text} left={<Icon name={icon} className="color-primary" />}>
                            {text}
                        </StripedItem>
                    ))}
                </StripedList>
            </ModalTwoContent>
            <ModalTwoFooter>
                <ButtonLike
                    as={SettingsLink}
                    path={`/dashboard?source=${REACTIVATE_SOURCE.reminderModal}#your-subscriptions`}
                    target="_blank"
                    fullWidth
                    color="norm"
                    onClick={markAsSeen}
                >{c('Cancellation reminder').t`Reactivate subscription`}</ButtonLike>
            </ModalTwoFooter>
        </ModalTwo>
    );
};

export default CancellationReminderModal;
import { PLANS } from '@proton/payments';
import type { APP_NAMES } from '@proton/shared/lib/constants';
import { getPlan } from '@proton/shared/lib/helpers/subscription';
import type { SubscriptionModel, UserModel } from '@proton/shared/lib/interfaces';

import { getBundleConfig } from './config/bundle';
import { getBundleProConfig } from './config/bundlePro';
import { getDrivePlusConfig } from './config/drivePlus';
import { getDuoConfig } from './config/duo';
import { getFamilyConfig } from './config/family';
import { getMailBusinessConfig } from './config/mailBusiness';
import { getMailEssentialConfig } from './config/mailEssential';
import { getMailPlusConfig } from './config/mailPlus';
import { getVisionaryConfig } from './config/visionary';
import type { PlanConfig } from './interface';

export const getReminderPageConfig = ({
    app,
    subscription,
    user,
}: {
    app?: APP_NAMES;
    subscription?: SubscriptionModel;
    user: UserModel;
}): PlanConfig | null => {
    const plan = getPlan(subscription);

    if (!plan || !subscription) {
        return null;
    }

    if (plan.Name === PLANS.MAIL) {
        return getMailPlusConfig({ plan, subscription, user });
    }

    if (plan.Name === PLANS.BUNDLE) {
        return getBundleConfig({ app, plan, subscription, user });
    }

    if (plan.Name === PLANS.FAMILY) {
        return getFamilyConfig({ plan, subscription, user });
    }

    if (plan.Name === PLANS.DUO) {
        return getDuoConfig({ app, plan, subscription, user });
    }

    if (plan.Name === PLANS.VISIONARY) {
        return getVisionaryConfig({ app, plan, subscription, user });
    }

    if (plan.Name === PLANS.DRIVE) {
        return getDrivePlusConfig({ plan, subscription, user });
    }

    if (plan.Name === PLANS.MAIL_PRO) {
        return getMailEssentialConfig({ plan, subscription, user });
    }

    if (plan.Name === PLANS.MAIL_BUSINESS) {
        return getMailBusinessConfig({ app, plan, subscription, user });
    }

    if (plan.Name === PLANS.BUNDLE_PRO_2024 || plan.Name === PLANS.BUNDLE_PRO) {
        return getBundleProConfig({ app, plan, subscription, user });
    }

    return null;
};
